DROP DATABASE IF EXISTS sah4test;
CREATE DATABASE IF NOT EXISTS sah4test;
USE sah4test;

DROP TABLE IF EXISTS detalleventas;
DROP TABLE IF EXISTS ventas;
DROP TABLE IF EXISTS precios;
DROP TABLE IF EXISTS articulos;
DROP TABLE IF EXISTS marcas;
DROP TABLE IF EXISTS familias;
DROP TABLE IF EXISTS clientes;
DROP TABLE IF EXISTS usuarios;

CREATE TABLE clientes (
 id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
 razon_social VARCHAR(100) NOT NULL UNIQUE,
 telefono VARCHAR(50) NOT NULL,
 email VARCHAR(100) NOT NULL
);

CREATE TABLE usuarios (
 id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
 nombre_usuario VARCHAR(50) NOT NULL UNIQUE,
 nombre_persona VARCHAR(100) NOT NULL,
 es_administrador BIT NOT NULL DEFAULT 0,
 passwd VARCHAR(100) NOT NULL
);

CREATE TABLE familias (
 id VARCHAR(50) NOT NULL PRIMARY KEY,
 nombre VARCHAR(100) NOT NULL UNIQUE
);

CREATE TABLE marcas (
 id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
 nombre VARCHAR(100) NOT NULL UNIQUE
);

CREATE TABLE articulos (
 id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
 descripcion VARCHAR(100) NOT NULL,
 codigo VARCHAR(50) NOT NULL,
 clave VARCHAR(50) NOT NULL,
 unidad VARCHAR(50) NOT NULL,
 existencia INT NOT NULL DEFAULT 0,
 codigo_barras VARCHAR(50) UNIQUE,
 id_marca BIGINT NOT NULL,
 id_familia VARCHAR(50) NOT NULL,
 CONSTRAINT fk_articulos_marcas FOREIGN KEY (id_marca) REFERENCES marcas (id),
 CONSTRAINT fk_articulos_familias FOREIGN KEY (id_familia) REFERENCES familias (id)
);

CREATE TABLE precios (
 id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
 precio DECIMAL(7,2) NOT NULL,
 fecha_registro DATETIME NOT NULL,
 estatus_activo BIT NOT NULL DEFAULT 1,
 id_articulo BIGINT NOT NULL,
 CONSTRAINT fk_precios_articulos FOREIGN KEY (id_articulo) REFERENCES articulos (id)
);

CREATE TABLE ventas (
 numero_venta BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
 fecha_venta DATETIME NOT NULL,
 id_cliente BIGINT NOT NULL,
 id_usuario BIGINT NOT NULL,
 CONSTRAINT fk_clientes_usuarios FOREIGN KEY (id_cliente) REFERENCES clientes (id),
 CONSTRAINT fk_ventas_usuarios FOREIGN KEY (id_usuario) REFERENCES usuarios (id)
);

CREATE TABLE detalleventas (
 id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
 cantidad TINYINT NOT NULL DEFAULT 1,
 id_precio BIGINT NOT NULL,
 numero_venta BIGINT NOT NULL,
 CONSTRAINT fk_detalleventas_precios FOREIGN KEY (id_precio) REFERENCES precios (id),
 CONSTRAINT fk_detalleventas_ventas FOREIGN KEY (numero_venta) REFERENCES ventas (numero_venta)
);



USE sah4test;

UPDATE articulos SET existencia=3 WHERE id=46;
UPDATE articulos SET existencia=6 WHERE id=60;
UPDATE articulos SET existencia=2 WHERE id=64;
UPDATE articulos SET existencia=9 WHERE id=66;
UPDATE articulos SET existencia=4 WHERE id=86;
